import sys

TAX = 0.08

def calc(items, c, d):
    t = 0
    for i in items:
        if i[2] == 'book':
            t = t + i[1] * i[3]
        elif i[2] == 'food':
            t = t + i[1] * i[3]
        else:
            t = t + i[1] * i[3] + i[1] * i[3] * TAX
    if c == 'SAVE10':
        if t > 50:
            t = t - t * 0.1
        else:
            t = t
    elif c == 'SAVE20':
        if t > 100:
            t = t - t * 0.2
    if d == 'express':
        t = t + 15
    elif d == 'standard':
        if t < 35:
            t = t + 5
    return round(t, 2)

def run_tests():
    cases = [
        (([('pen', 2.5, 'office', 4)], None, 'standard'), 15.8),
        (([('novel', 12.0, 'book', 2), ('apple', 0.5, 'food', 10)], 'SAVE10', 'express'), 44.0),
        (([('novel', 30.0, 'book', 2)], 'SAVE10', 'pickup'), 54.0),
        (([('lamp', 60.0, 'home', 2)], 'SAVE20', 'standard'), 103.68),
        (([], None, 'standard'), 5),
    ]
    failed = 0
    for args, expected in cases:
        actual = calc(*args)
        if actual == expected:
            print(f"PASS calc{args} == {expected}")
        else:
            failed += 1
            print(f"FAIL calc{args}: expected {expected}, got {actual}")
    print(f"{len(cases) - failed} passed, {failed} failed")
    if failed:
        sys.exit(1)


run_tests()
